  "games.ankjod.rules.glance.3": "No digit repeats within a run",
  "games.ankjod.rules.rules.1.body": "A clue on the left sums the run to its right; a clue above sums the run below it.",
  "games.ankjod.rules.rules.1.h": "Runs",
  "games.ankjod.rules.rules.2.body": "Only 1–9. A digit can appear once per run, but can repeat in different runs.",
  "games.ankjod.rules.rules.2.h": "Digits",
  "games.ankjod.rules.rules.3.body": "Every puzzle has exactly one solution, checked by our solver. Difficulty reflects the techniques you need: Easy uses unique sums, Medium adds crossing runs, Hard needs digit placement within runs, Expert needs short “what if” eliminations.",
  "games.ankjod.rules.rules.3.h": "One answer",
  "games.ankjod.rules.rules.4.body": "Pencil notes, auto-notes, the sums helper (which digit sets fit a run), undo/redo and hints (reveal a cell or explain the next deduction) are always allowed. Mistake marking can be off, shown as you go, or only when you tap Check.",
  "games.ankjod.rules.rules.4.h": "Tools",
  "games.ankjod.rules.rules.5.body": "One board a day, the same for everyone; your first try counts (leave and Continue to finish it), ranked by time plus 30 seconds per hint. Replays and past Dailies from the archive are practice.",
  "games.ankjod.rules.rules.5.h": "Daily",
