  "games.badminton.rallies_rallies_longest_longest_shots_average_avgrally": "Rallies {{rallies}} · longest {{longest}} shots · average {{avgRally}}{{value}}",
  "games.badminton.rally_never_ended": "Rally never ended",
  "games.badminton.rally_point_scoring_a_game_is": "Rally point scoring. A game is won at 21 with a 2-point lead; from 20-all the first side 2 points clear wins; at 29-all the 30th point wins. Best of 3 games; the game winner serves first in the next game.",
  "games.badminton.rated": "rated",
  "games.badminton.rating": "rating",
  "games.badminton.receiver_not_ready_caught_in_the": "Receiver not ready, caught in the net after passing over, both faulted at once, a broken shuttle or an unforeseen event — the rally is replayed by the same server.",
