  "games.badminton.retriever": "Retriever",
  "games.badminton.rules.bots": "Bots",
  "games.badminton.rules.botsBody": "Beginner, Club, County and Pro, each as an All-rounder, Attacker, Retriever or Net player. Bots are always labelled as bots.",
  "games.badminton.rules.formats": "Formats",
  "games.badminton.rules.glance.1": "Swipe (or tap) as the bar crosses the green",
  "games.badminton.rules.glance.2": "Every rally scores a point",
  "games.badminton.rules.glance.3": "Best of 3 games to 21 — win by 2, 30 caps it",
  "games.badminton.rules.play": "Playing",
  "games.badminton.rules.playBody": "Release as the bar crosses the green band — the centre is your best contact. Swipe up to choose the shot: a longer swipe goes deeper, a quick swipe attacks (smash, drive, kill), sideways aims. Hold still for a moment before swiping to disguise it. A plain tap plays the natural shot. You run to the shuttle yourself; drag your marker to change where you recover to.",
  "games.badminton.rules.playMore": "You can only smash from above your head, and only net-shot when you reach the net early. Long rallies tire you (slower feet, weaker shots); you recover between points and at intervals. Doubles: attack front-and-back, defend side-by-side — your partner rotates with you.",
  "games.badminton.rules.rules.1.body": "Your player runs to the shuttle by itself — drag your marker to change where you wait. When it’s your shot, swipe up as the bar crosses the green: a long swipe plays deep (clear, lift, high serve), a short one plays to the front (drop, net shot, low serve), a quick one attacks (smash, drive, flick, kill), and sideways aims. Hold still for a moment before swiping to disguise it. A plain tap plays the natural shot for where you are. Good timing, being in position and fresh legs make a better shot; you can only smash a shuttle that’s above you.",
  "games.badminton.rules.rules.1.h": "Controls",
  "games.badminton.rules.rules.10.body": "Standard: best of 3 games to 21 (rated in Live singles). Single game to 21 and Quick 11 (best of 3 to 11, 2-point lead, capped at 15 — a {{@chaupaal}} quick format, not a BWF one) are unrated.",
  "games.badminton.rules.rules.10.h": "Formats",
  "games.badminton.rules.rules.11.body": "Our server resolves every rally with its own seed: your phone only sends your swipe and the moment you played it, allowed for your connection up to a fixed cap (you’re warned before a rated match on a slow connection). Miss your turn and a weak lift is played for you; three missed turns in a row forfeits. If someone drops mid-rally, the rally is a let and play pauses until they’re back — no return in time forfeits. Line calls and shot speeds shown are simulated. Doubles pairs friends, bots or matchmade players 2 v 2 and is unrated. Virtual chips only.",
  "games.badminton.rules.rules.11.h": "Live",
  "games.badminton.rules.rules.2.body": "In Match settings → More: tap anywhere in the green and the shot is picked for you. Matches with a Simple player are unrated.",
  "games.badminton.rules.rules.2.h": "Simple controls",
  "games.badminton.rules.rules.3.body": "Bots come in four levels (Beginner, Club, County, Pro) and four styles: All-rounder, Attacker (smashes whenever it can), Retriever (gets everything back) and Net player (tight at the net). Drills — serve practice, smash defence and net play — are solo and unrated, with a score and your personal best.",
  "games.badminton.rules.rules.3.h": "Bots and drills",
  "games.badminton.rules.rules.4.body": "Every rally wins a point for the side that wins it. A game is won at 21 with a 2-point lead; from 20-all the first side 2 points clear wins, and at 29-all the 30th point wins. Standard is best of 3 games; the winner of a game serves first in the next.",
  "games.badminton.rules.rules.4.h": "Scoring",
  "games.badminton.rules.rules.5.body": "A short interval when the leading score reaches 11, and a longer one between games — either player can tap Ready to resume early. Players change ends after each game, and in the deciding game when the leading score reaches 11.",
  "games.badminton.rules.rules.5.h": "Intervals and ends",
  "games.badminton.rules.rules.6.body": "Serve from the right service court when the server’s score is even (0, 2, 4 …) and the left when it is odd, diagonally to the receiver. The singles court is long and narrow: the serve may land up to the back line.",
  "games.badminton.rules.rules.6.h": "Singles service",
  "games.badminton.rules.rules.7.body": "One service per side. If the serving side wins the rally, the same server serves again from the other court. If the receiving side wins, they score and serve next: their player in the court matching their score (right if even, left if odd) serves. Players only change courts when they win a point on their own serve. The receiver is always diagonal. The doubles court is wide, but the serve must land before the doubles long service line.",
  "games.badminton.rules.rules.7.h": "Doubles service",
  "games.badminton.rules.rules.8.body": "Shuttle out or into the net; touching the net; hitting twice or both partners hitting in succession; obstructing the opponent. Service faults: struck above 1.15 m, feet moving, short of the short service line, past the long line or outside the box.",
  "games.badminton.rules.rules.8.h": "Faults",
  "games.badminton.rules.rules.9.body": "The rally is replayed with no point: the receiver wasn’t ready, the shuttle caught on the net on a return, both sides faulted, the shuttle came apart, or play was disturbed.",
  "games.badminton.rules.rules.9.h": "Lets",
