  "games.bluff.roomSettings": "Table settings",
  "games.bluff.rules": "Rules",
  "games.bluff.rules.glance.1": "Play cards face down and say what they are",
  "games.bluff.rules.glance.2": "Anyone can call \"Bluff!\" before the timer ends",
  "games.bluff.rules.glance.3": "First to empty their hand — and survive the call — wins",
  "games.bluff.rules.rules.1.body": "3–8 players. One deck for up to 5 players, two decks from 6. All the cards are dealt out; some players may hold one more.",
  "games.bluff.rules.rules.1.h": "Table",
  "games.bluff.rules.rules.2.body": "Claims run in order: Aces, Twos, Threes … Kings, then Aces again. On your turn you must play 1–4 cards (up to 6 with two decks) face down and claim they are the current rank — true or not. There is no passing.",
  "games.bluff.rules.rules.2.h": "Sequence",
  "games.bluff.rules.rules.3.body": "The leader names any rank and plays. Each next player claims the same rank or passes. When everyone else has passed in a row, the pile is set aside out of play and the last player who put cards down leads a new rank.",
  "games.bluff.rules.rules.3.h": "Follow the rank",
  "games.bluff.rules.rules.4.body": "After every play there is a short window (5 seconds by default). Anyone still holding cards can call \"Bluff!\" — the first call wins the race. Only that last play is turned over.",
  "games.bluff.rules.rules.4.h": "Calling Bluff",
  "games.bluff.rules.rules.5.body": "If any card isn’t the claimed rank, the player who played picks up the whole pile. If every card matches, the caller picks it up. Sequence then carries on with the next rank from the player after the one who played. In Follow the rank the winner of the challenge leads a new rank.",
  "games.bluff.rules.rules.5.h": "Who picks up",
  "games.bluff.rules.rules.6.body": "You win when your hand is empty and you survive your last play: either nobody calls in time, or someone calls and your cards were true. Caught on your last play? You pick up the pile and keep going. With \"Play on for places\" the game continues until one player is left holding cards.",
  "games.bluff.rules.rules.6.h": "Winning",
  "games.bluff.rules.rules.7.body": "Off by default. When on, two jokers per deck are added and a joker always counts as the claimed rank.",
  "games.bluff.rules.rules.7.h": "Jokers",
  "games.bluff.rules.rules.8.body": "25 seconds per turn. A missed turn passes (Follow the rank) or plays one card; after 3 missed turns, or if you leave, a bot takes your seat and hand and you forfeit. Cards are dealt on our server; face-down cards are never sent to anyone until they are turned over. Very long games end after 60 plays per player: fewest cards wins. Bots at the table keep it friendly (no stakes).",
  "games.bluff.rules.rules.8.h": "Live",
  "games.bluff.rules.ruleset.name": "Bluff",
  "games.bluff.rules.ruleset.source": "Classic Bluff / Cheat / I Doubt It rules · two regional styles",
