  "games.brickbreaker.rules.glance.3": "Lose the last ball and you lose a life",
  "games.brickbreaker.rules.rules.1.body": "Where the ball lands on the paddle sets its angle: the centre sends it almost straight up, the edges send it out at up to 60°. The ball never travels flatter than 15° so it can’t loop sideways forever.",
  "games.brickbreaker.rules.rules.1.h": "Aiming",
  "games.brickbreaker.rules.rules.2.body": "The ball starts a little faster on later levels and speeds up slightly with every brick, up to a fixed top speed.",
  "games.brickbreaker.rules.rules.2.h": "Speed",
  "games.brickbreaker.rules.rules.3.body": "Numbered bricks take that many hits. Steel (grey, no number) can’t be broken. Gold scores extra. Bombs break the bricks around them. Moving bricks slide from side to side.",
  "games.brickbreaker.rules.rules.3.h": "Bricks",
  "games.brickbreaker.rules.rules.4.body": "Every normal brick has an 8% chance to drop a power-up; bricks marked with a star always drop one. Which one: Wide paddle 22% (12 s) · Multi-ball 18% (two extra balls) · Slow ball 18% (8 s) · Sticky 16% (the next 3 catches hold the ball; tap to release) · Laser 14% (8 s, fires automatically) · Extra ball 12% (max 5 lives).",
  "games.brickbreaker.rules.rules.4.h": "Power-ups",
  "games.brickbreaker.rules.rules.5.body": "Campaign: 60 levels, three lives each, up to three stars. Endless: seeded waves, one after another, until you run out of lives. Daily: one level a day, the same for everyone; your first try counts.",
  "games.brickbreaker.rules.rules.5.h": "Modes",
