  "games.carrom.rules.glance.1": "Flick the striker from your baseline to pocket your own men",
  "games.carrom.rules.glance.2": "Pocket the Queen after one of yours, then cover it on the same or next shot",
  "games.carrom.rules.glance.3": "Clear your men first — you score one point for each of theirs left",
  "games.carrom.rules.rules.1.body": "Men start in the centre with the Queen on the red spot. A toss decides who breaks; the breaker plays white. The break must touch a man — three tries, then the turn passes. No due is taken on the break.",
  "games.carrom.rules.rules.1.h": "Setup and break",
  "games.carrom.rules.rules.10.body": "Partners sit opposite and play the same colour. Turns go to the right, so partners alternate with opponents. The break moves to the right each board. Dues are placed by the player on the shooter’s right.",
  "games.carrom.rules.rules.10.h": "Doubles",
  "games.carrom.rules.rules.11.body": "Casual: any man is yours. White 20, black 10, Queen 50 (it still needs a cover). First to 160 wins. Unrated.",
  "games.carrom.rules.rules.11.h": "Freestyle",
  "games.carrom.rules.rules.12.body": "Singles Standard and Quick are rated; Freestyle and doubles are not. Leaving forfeits the game (a whole team in doubles). Optional virtual-chip stake, never with bots.",
  "games.carrom.rules.rules.12.h": "Live",
  "games.carrom.rules.rules.2.body": "Place the striker on your baseline, touching both lines, either covering a base circle completely or clear of it, and not touching the arrow line or any man.",
  "games.carrom.rules.rules.2.h": "Striker",
  "games.carrom.rules.rules.3.body": "Pocket one of your men (or cover the Queen) and you shoot again. Otherwise the turn passes to your right. Pocketing an opponent’s man counts for them and ends your turn.",
  "games.carrom.rules.rules.3.h": "Your turn",
  "games.carrom.rules.rules.4.body": "You may only pocket the Queen after you have pocketed one of your own men and while you owe no due. Cover it by pocketing one of yours on the same stroke or the very next one; otherwise it goes back to the centre.",
  "games.carrom.rules.rules.4.h": "Queen",
  "games.carrom.rules.rules.5.body": "Pocketing the striker is a foul: one of your pocketed men comes back as a due (plus any man pocketed on that stroke), and the turn passes unless you also pocketed one of yours. The opponent places dues inside the outer circle, off the centre spot, touching no other man. If you have none pocketed, the due waits until you do. A pending Queen goes back.",
  "games.carrom.rules.rules.5.h": "Fouls and dues",
  "games.carrom.rules.rules.6.body": "20 seconds per stroke in Live (the ICF allows 15; we add five for touch aiming). Running out of time is a foul: one man back and the turn passes. Three in a row forfeits. Placing a due has 15 seconds.",
  "games.carrom.rules.rules.6.h": "Shot clock",
  "games.carrom.rules.rules.7.body": "Pocketing your opponent’s last man, or your last man while the Queen is still on the board, loses the board. Finishing with the striker brings those men back with a due.",
  "games.carrom.rules.rules.7.h": "Last men",
  "games.carrom.rules.rules.8.body": "The board winner scores one point for each opponent man left, plus 3 for the Queen if they covered it — only while their score is 21 or less. A board is worth at most 12.",
  "games.carrom.rules.rules.8.h": "Board score",
  "games.carrom.rules.rules.9.body": "First to 25 points, or the leader after 8 boards. Level after 8: one extra board, with a toss for the break. Quick plays one board.",
  "games.carrom.rules.rules.9.h": "Game",
