  "games.ludo.rules.glance.1": "Roll a 6 to bring a token out",
  "games.ludo.rules.glance.2": "Race all four tokens home",
  "games.ludo.rules.glance.3": "Land on a rival to send it back to base",
  "games.ludo.rules.rules.1.body": "Roll one die. A 6 brings a token out of base and rolls again; three 6s in a row lose the turn. Tokens move clockwise.",
  "games.ludo.rules.rules.1.h": "Turns",
  "games.ludo.rules.rules.2.body": "Landing exactly on a rival token sends it back to base — except on safe squares (every start square and the stars).",
  "games.ludo.rules.rules.2.h": "Captures",
  "games.ludo.rules.rules.3.body": "You need the exact roll to reach home. A token reaching home earns a bonus roll.",
  "games.ludo.rules.rules.3.h": "Home",
  "games.ludo.rules.rules.4.body": "The first player with all four tokens home wins; play continues for the other places. Quick mode: every token starts on its start square and the first token home wins.",
  "games.ludo.rules.rules.4.h": "Winning",
  "games.ludo.rules.rules.5.body": "The host can pick: enter on 1 or 6 · capture bonus roll · must capture before entering home · blocks (two of your tokens on a square can’t be passed) · safe squares off · Teams 2v2 (partners sit opposite). They lock at the start and show in the lobby.",
  "games.ludo.rules.rules.5.h": "House rules",
  "games.ludo.rules.rules.6.body": "Live dice are rolled on our server — never on a phone — with no weighting. Open Dice history to see every roll.",
  "games.ludo.rules.rules.6.h": "Fair dice",
  "games.ludo.rules.rules.7.body": "If you time out, your most advanced token moves for you. Miss three turns or leave and a bot finishes your game; you forfeit your place.",
  "games.ludo.rules.rules.7.h": "Leaving",
  "games.ludo.rules.rules.8.body": "Optional virtual-chip stake. Everyone antes; 2 players: winner takes both · 3: 70/30 · 4: 60/30/10. Teams: winners take the losers’ stakes. Bots never take chips.",
  "games.ludo.rules.rules.8.h": "Payouts",
