  "games.quiz.rules.glance.3": "Correct and fast scores most",
  "games.quiz.rules.rules.1.body": "A correct answer scores 600 + 400 × (time left ÷ time limit): 1000 for an instant answer, 600 at the buzzer. Wrong or no answer scores 0.",
  "games.quiz.rules.rules.1.h": "Scoring",
  "games.quiz.rules.rules.2.body": "Equal scores are split by total answer time — lower wins. Unanswered questions count the full time. Exactly equal is a draw.",
  "games.quiz.rules.rules.2.h": "Ties",
  "games.quiz.rules.rules.3.body": "Questions open at the same server time for everyone. Your answer time is measured on the server, minus half your measured network round trip (at most 0.25 s), so a slower connection is not punished. Answers are checked on the server; nobody sees the right answer before the reveal.",
  "games.quiz.rules.rules.3.h": "Fair timing",
  "games.quiz.rules.rules.4.body": "Live 1v1, rated. 10 questions, 15 seconds each, the same questions and option order for both players, matched to your ratings. You see when your opponent has answered, never what they picked.",
  "games.quiz.rules.rules.4.h": "Duel",
  "games.quiz.rules.rules.5.body": "Dropping mid-question simply counts as no answer; rejoin and carry on. Leaving a Duel, or staying away for 60 seconds, forfeits and counts as a rated loss.",
  "games.quiz.rules.rules.5.h": "Disconnects",
  "games.quiz.rules.rules.6.body": "2–50 players in a room. The host picks categories, length, time per question and difficulty, and can run a big-screen view while everyone answers on their phone.",
  "games.quiz.rules.rules.6.h": "Party Quiz",
  "games.quiz.rules.rules.7.body": "10 questions, the same for everyone, new at your local midnight. One attempt; leaderboards and streaks after you finish.",
