  "games.rummy.roomSettings": "Table settings",
  "games.rummy.rules": "Rules",
  "games.rummy.rules.glance.1": "Draw a card, throw a card",
  "games.rummy.rules.glance.2": "Group your hand into sequences (runs) and sets",
  "games.rummy.rules.glance.3": "13-card: declare with a valid hand · Gin: knock with little deadwood",
  "games.rummy.rules.rules.1.body": "2–6 players, 13 cards each. Up to 2 players use one deck with one printed joker; 3–6 use two decks with two. A card is cut face up: every card of that rank is a wild joker for the deal (a cut printed joker makes Aces wild). The cut card stays out of play.",
  "games.rummy.rules.rules.1.h": "13-card: deal",
  "games.rummy.rules.rules.10.body": "Knock when your unmatched cards (deadwood: face cards 10, Ace 1) total 10 or less (the table can set 5, or 0 for Gin only). All 10 in melds is Gin: +25 and the opponent can’t lay off. After a knock the defender may lay off deadwood on the knocker’s melds. The knocker scores the difference; if the defender has equal or less deadwood it’s an undercut: the defender scores the difference +25. Big Gin (optional): all 11 cards melded, +31.",
  "games.rummy.rules.rules.10.h": "Gin: knock and Gin",
  "games.rummy.rules.rules.11.body": "First to 100 (or 50). Simple scoring adds hand scores. Classic adds 100 for the game and 25 per hand won (box), doubled on a shutout. If the stock gets down to two cards with no knock, the hand is a draw.",
  "games.rummy.rules.rules.11.h": "Gin: game",
  "games.rummy.rules.rules.12.body": "30 seconds per turn (25 in Gin), then your extra-time bank for the match. A missed turn auto-plays (draw and throw); miss again and you auto-drop (Deals: full count, Gin: forfeit). Hands are dealt on our server and only you ever receive your cards. Two players are rated; bots at the table keep it friendly. Chip tables are 18+.",
  "games.rummy.rules.rules.12.h": "Live",
  "games.rummy.rules.rules.2.body": "Draw from the closed deck or take the top open card, then throw one card. You can’t take a joker from the open pile (except the very first open card), and you can’t throw back the card you just picked.",
  "games.rummy.rules.rules.2.h": "13-card: your turn",
  "games.rummy.rules.rules.3.body": "Group all 13 cards into sequences and sets. You need at least two sequences, and at least one of them must be pure (no joker). Sets are 3–4 cards of one rank in different suits. Sequences are 3+ cards of one suit in order; Ace can be low (A-2-3) or high (Q-K-A) but not both (no K-A-2).",
  "games.rummy.rules.rules.3.h": "13-card: a valid show",
  "games.rummy.rules.rules.4.body": "Put your 14th card on Finish with your groups. A valid show wins the deal and the others then have 45 seconds to group their cards; anything not grouped is counted for them. A wrong show costs 80 and play goes on.",
  "games.rummy.rules.rules.4.h": "13-card: declare",
  "games.rummy.rules.rules.5.body": "A, K, Q and J score 10, number cards their face value, jokers 0. If your hand has no pure sequence everything counts; with a pure but no second sequence, everything except the pure sequence counts. The most you can lose in a deal is 80. Drop before your first draw for 20, later for 40 (Pool 201: 25 / 50). Leaving or timing out mid-deal counts 80.",
  "games.rummy.rules.rules.5.h": "13-card: points",
  "games.rummy.rules.rules.6.body": "One deal. The winner collects the losers’ points × the table’s rate (in virtual chips; a friendly table only keeps score).",
  "games.rummy.rules.rules.6.h": "Points",
  "games.rummy.rules.rules.7.body": "Points add up deal after deal; reach the limit and you’re out. The last player left wins the pool. An eliminated player may rejoin once (at a chip table, for another entry fee) while the leader has 79 or less (174 in Pool 201), starting one point above the highest score.",
  "games.rummy.rules.rules.7.h": "Pool 101 / 201",
  "games.rummy.rules.rules.8.body": "A fixed 2, 3 or 6 deals. Everyone starts with 80 × deals chips of score; losers pay their points to each deal’s winner. There is no drop. Most chips at the end wins; a tie plays one more deal between the tied players.",
  "games.rummy.rules.rules.8.h": "Deals",
  "games.rummy.rules.rules.9.body": "Two players, 10 cards each, one deck, no jokers; Ace is always low. The non-dealer may take the upcard, then the dealer; if both pass, the non-dealer draws from the stock. Each turn: draw from the stock or discard pile, then discard.",
  "games.rummy.rules.rules.9.h": "Gin: play",
