  "games.streetcricket.review.title": "Review?",
  "games.streetcricket.review_by_batter": "review (batter): {{result}}",
  "games.streetcricket.review_by_bowler": "review (bowler): {{result}}",
  "games.streetcricket.review_caught_behind": "Review · caught behind",
  "games.streetcricket.review_lbw": "Review · LBW",
  "games.streetcricket.review_one_per_side_per_innings": "Review: one per side per innings on LBW or caught behind — kept on umpire’s call.",
  "games.streetcricket.reviews_left_secs_s": "{left, plural, one {# review left} other {# reviews left}} · {{secs}}s",
  "games.streetcricket.riders_on_the_rope_fewer_fours": "Riders on the rope · fewer fours · easy singles",
  "games.streetcricket.risk.bouncer": "a wide or no-ball",
  "games.streetcricket.risk.green": "stop the needle in the green",
  "games.streetcricket.risk.high": "High",
  "games.streetcricket.risk.loose": "a loose ball",
  "games.streetcricket.risk.low": "Low",
  "games.streetcricket.risk.med": "Medium",
  "games.streetcricket.risk.miss": "a miss can be",
  "games.streetcricket.risk.wide": "a wide",
  "games.streetcricket.risk.yorker": "a full toss or no-ball",
  "games.streetcricket.risk_lvl_a_miss_can_be_what": "Risk {{lvl}} · a miss can be {{what}} · stop the needle in the green",
  "games.streetcricket.rules": "Rules",
  "games.streetcricket.rules.glance.1": "Bowl: pick line, length and ball, then stop the needle in the green",
  "games.streetcricket.rules.glance.2": "Bat: read the landing marker and tap a shot as the ball arrives",
  "games.streetcricket.rules.glance.3": "Most runs after both innings wins",
  "games.streetcricket.rules.rules.1.body": "Each side bats once. An innings ends when the overs run out, the wickets fall, or the chasing side passes the target. Super Quick is 1 over and 1 wicket, Quick 2 and 2, Standard 5 and 3, Long 10 and 5. In 1v1 you bat every \"life\" yourself: each wicket brings you back as the next batter.",
  "games.streetcricket.rules.rules.1.h": "Innings",
  "games.streetcricket.rules.rules.10.body": "No LBW. You can’t be out first ball. Tip and run: if the bat touches the ball you must run (toggle). A one-bounce catch counts (toggle). Unrated.",
  "games.streetcricket.rules.rules.10.h": "Backyard rules",
  "games.streetcricket.rules.rules.11.body": "A coin toss first (the other player calls; the winner bats or bowls). In a rematch, the previous toss loser chooses. Our server resolves every ball: the bowler sends a plan and when they stopped the needle, the batter sends a shot and the moment they tapped, and the server decides the outcome — the variation stays hidden until the ball is played. Your connection is allowed for, up to a fixed cap. If you drop out, the server bowls a stock ball or defends for you; three missed turns forfeits. Only Standard is rated; virtual chips only. Friends can watch the scorecard and commentary.",
  "games.streetcricket.rules.rules.11.h": "Live",
  "games.streetcricket.rules.rules.12.body": "Short lines on key moments only (boundaries, wickets, milestones, reviews, the last over), in a calm analyst or excited fan voice, with an optional read-aloud. When AI commentary is on it is batched once per over and marked AI; otherwise lines come from our own library and never repeat in a match. A short recap goes on the share card.",
  "games.streetcricket.rules.rules.12.h": "Commentary",
  "games.streetcricket.rules.rules.2.body": "An over is 6 legal balls. A wide is 1 extra plus any runs; it is re-bowled and isn’t a ball faced. A no-ball is 1 extra plus the runs off the bat, is re-bowled, and the next ball is a free hit. Byes and leg-byes go to extras, not the bowler.",
  "games.streetcricket.rules.rules.2.h": "Overs and extras",
  "games.streetcricket.rules.rules.3.body": "Bowled, caught, LBW, run out, stumped or hit wicket. Off a no-ball or a free hit you can only be run out. Off a wide you can be stumped, run out or hit wicket. A free hit carries over if the next ball is a wide or another no-ball.",
  "games.streetcricket.rules.rules.3.h": "Getting out",
  "games.streetcricket.rules.rules.4.body": "Each over, pick pace or spin and a field: Attacking (catchers in, risky singles), Balanced, Defensive (riders on the rope, easy singles), Protect off-side or Protect leg-side (seals that boundary, opens the other). Each ball, pick a line (off, middle, leg, wide), a length (yorker, full, good, short, bouncer) and a ball: pace has slower, cutter, bouncer and yorker; spin has turn in, turn away and the arm ball. Stop the accuracy needle in the green — harder targets missed become full tosses, wides or no-balls. In 1v1 one bowler bowls every over (the consecutive-overs law is waived).",
  "games.streetcricket.rules.rules.4.h": "Bowling",
  "games.streetcricket.rules.rules.5.body": "Watch the landing marker, then tap one of eight shots as the ball reaches the glowing band: drive, cut, pull, sweep, loft, flick, defend or leave. Early, perfect or late timing and how well the shot suits the line and length decide the contact. Against spin you can step out to hit bigger (miss it and you may be stumped). Set your running before the ball: Hold, Take 1 or Push 2 — pushing for the extra run risks a run out, more so against an attacking field or when you hit it straight. If you don’t tap in time, you defend late automatically. The Set meter shows confidence: it builds with good contact and drops after edges and play-and-misses, worth up to ±8% contact.",
  "games.streetcricket.rules.rules.5.h": "Batting",
  "games.streetcricket.rules.rules.6.body": "Each match rolls a pitch shown before the toss: Flat (true bounce), Green (pace carries and seams, edges fly), Dusty (spin grips and turns) or Street tarmac for Gully (skiddy, fast outfield).",
  "games.streetcricket.rules.rules.6.h": "Pitch",
  "games.streetcricket.rules.rules.7.body": "One review per side per innings, for LBW and caught behind only. The batter reviews an out, the bowler a not out. Ball-tracking and edge detection are a simulation from the game’s own model, not real broadcast tech. On LBW, a ball inside the shaded band is umpire’s call: the on-field decision stays and you keep your review. You lose it only when the decision stands.",
  "games.streetcricket.rules.rules.7.h": "Reviews (Standard)",
  "games.streetcricket.rules.rules.8.body": "The side that bats second wins by the wickets it has left (and the balls to spare); otherwise the side batting first wins by the runs between them. Level scores go to a Super Over (the chasing side bats first; repeat once, then boundary count), a shared tie, or boundary count, as the host picks.",
  "games.streetcricket.rules.rules.8.h": "Result",
  "games.streetcricket.rules.rules.9.body": "No LBW. One tip one hand: a one-handed catch after one bounce is out. Six and out: clearing the wall is out (toggle). Last man stands: the last batter bats on alone (toggle). A free hit still protects you from six and out. Unrated.",
  "games.streetcricket.rules.rules.9.h": "Gully rules",
  "games.streetcricket.rules.ruleset.name": "Street Cricket",
