  "games.tambola.prizesT": "Prizes",
  "games.tambola.pts": "pts",
  "games.tambola.publicFail": "Couldn’t find a table — try again",
  "games.tambola.publicNote": "Wallet chips, 18+. Buy 1–6 tickets in the lobby. Prizes are shares of the ticket pot; a bot’s prize or an unclaimed one goes back to the buyers. Starts 45 seconds after the table opens.",
  "games.tambola.publicSub": "Buy chip tickets · starts in under a minute · 18+",
  "games.tambola.publicTable": "Public table",
  "games.tambola.publicTitle": "Public table",
  "games.tambola.public_table_value_a_ticket_18": "Public table · ⚡{{value}} a ticket · 18+",
  "games.tambola.restart": "New game",
  "games.tambola.restartConfirm": "Start a new game? The numbers called so far are cleared.",
  "games.tambola.resume": "Resume",
  "games.tambola.roomSettings": "Game settings",
  "games.tambola.rules": "Rules",
  "games.tambola.rules.glance.1": "Numbers are called one at a time",
  "games.tambola.rules.glance.2": "Mark them on your ticket",
  "games.tambola.rules.glance.3": "Complete a pattern and tap Claim before anyone else",
  "games.tambola.rules.rules.1.body": "Each ticket is 3 rows × 9 columns with 15 numbers — 5 in every row. Column 1 holds 1–9, column 2 holds 10–19 … the last column 80–90, sorted top to bottom. A full sheet of 6 tickets holds every number from 1 to 90 exactly once. Buy 1–6 tickets, or a full sheet.",
  "games.tambola.rules.rules.1.h": "Tickets (90-ball)",
  "games.tambola.rules.rules.2.body": "Numbers are drawn at random on our server, one every 5, 8 or 12 seconds (the host picks and can pause). Every number called stays on the board. The caller can use traditional calls (\"Two little ducks, 22\") — a toggle in settings.",
  "games.tambola.rules.rules.2.h": "Calling",
  "games.tambola.rules.rules.3.body": "The host picks the prizes: Early Five (any 5 numbers), Top, Middle and Bottom Line, Four Corners (first and last numbers of the top and bottom rows), Full House (all 15), then 2nd and 3rd Full House. Extras: Early Seven, Star (corners + the middle number), Breakfast / Lunch / Dinner (columns 1–3, 4–6, 7–9).",
  "games.tambola.rules.rules.3.h": "Prizes",
  "games.tambola.rules.rules.4.body": "Tap Claim on a prize when your ticket has it. It’s checked against the numbers called so far. The first valid claim wins. A valid claim for the same prize within 1 second — on a ticket that was already complete at the same number — shares it. 2nd Full House opens once the Full House is won.",
  "games.tambola.rules.rules.4.h": "Claims",
  "games.tambola.rules.rules.5.body": "A wrong claim is a bogey: that ticket can’t win that prize any more (the host can choose a warning first). One claim every 1.5 seconds per player.",
  "games.tambola.rules.rules.5.h": "Bogey",
  "games.tambola.rules.rules.6.body": "A 5×5 card: B 1–15, I 16–30, N 31–45, G 46–60, O 61–75 with a free centre. Patterns: any line (row, column or diagonal), four corners, X, blackout (the whole card) or the host’s own pattern. Calls include the letter (\"B 12\").",
  "games.tambola.rules.rules.6.h": "75-ball Bingo",
  "games.tambola.rules.rules.7.body": "Private rooms play just for fun (points) or for table chips that stay in the room. Public tables use wallet chips: each ticket costs the table price, prizes are shares of the ticket pot, and any prize won by a bot or never claimed goes back to the buyers. Public tables are 18+. Virtual chips only — they can’t be bought or cashed out.",
  "games.tambola.rules.rules.7.h": "Chips",
  "games.tambola.rules.rules.8.body": "Run a game for people in the same room with no sign-in and no connection: draws, voice, board, pause. Print or share real tickets; each carries a code so you can Check a ticket when someone shouts Housie.",
  "games.tambola.rules.rules.8.h": "Caller mode",
  "games.tambola.rules.ruleset.source": "Classic {{@tambola}} / Housie (90-ball) and Bingo (75-ball) rules",
