  "games.teenpatti.practiceNote": "Practice uses play chips — your wallet is untouched.",
  "games.teenpatti.practice_label_play_chips": "Practice · {{label}} · play chips",
  "games.teenpatti.r.colour": "Colour",
  "games.teenpatti.r.colourD": "Three of one suit, not in a row. Compare the highest card first.",
  "games.teenpatti.r.high": "High card",
  "games.teenpatti.r.highD": "Nothing else: highest card, then the next.",
  "games.teenpatti.r.pair": "Pair",
  "games.teenpatti.r.pairD": "Two of a rank; the higher pair wins, then the odd card.",
  "games.teenpatti.r.pure": "Pure sequence",
  "games.teenpatti.r.pureD": "Three in a row, one suit.",
  "games.teenpatti.r.seq": "Sequence",
  "games.teenpatti.r.seqD": "Three in a row. A-K-Q is the top, A-2-3 second, then K-Q-J… down to 4-3-2. No K-A-2.",
  "games.teenpatti.r.trail": "Trail",
  "games.teenpatti.r.trailD": "Three of a kind. A-A-A is the best hand.",
  "games.teenpatti.raise": "Raise",
  "games.teenpatti.raise_cost": "Raise {{cost}}",
  "games.teenpatti.rankNote": "Suits never rank. On equal hands at a show, the player who asked loses; at a pot-limit show, equal hands split.",
  "games.teenpatti.rankTitle": "Hand rankings",
  "games.teenpatti.roomSettings": "Table settings",
  "games.teenpatti.rules": "Rules",
  "games.teenpatti.rules.glance.1": "Everyone pays the boot and gets three cards",
  "games.teenpatti.rules.glance.2": "Bet blind, or look and bet double — or pack",
  "games.teenpatti.rules.glance.3": "Best three-card hand at the show wins the pot",
  "games.teenpatti.rules.rules.1.body": "3–7 players, one deck. Everyone puts in the boot; the first stake equals the boot. Bots fill empty seats (then nothing is at stake).",
  "games.teenpatti.rules.rules.1.h": "Table",
  "games.teenpatti.rules.rules.10.body": "Virtual chips only — they can’t be bought or cashed out. Your stack is the buy-in (or your balance if lower); after the last hand everyone’s result is their stack minus the buy-in. {{@teenpatti}} is 18+. Unrated.",
  "games.teenpatti.rules.rules.10.h": "Chips",
  "games.teenpatti.rules.rules.2.body": "Blind players bet the current stake without looking. Once you look (Seen), you bet double. After the blind limit (4 blind bets by default) you must look.",
  "games.teenpatti.rules.rules.2.h": "Blind or seen",
  "games.teenpatti.rules.rules.3.body": "Chaal matches the stake (seen: 2×). Raise doubles the stake (a seen raise costs 4× the old stake). The stake can’t go above 16 × boot.",
  "games.teenpatti.rules.rules.3.h": "Chaal and raise",
  "games.teenpatti.rules.rules.4.body": "Fold your hand; what you put in stays in the pot. Running out of time packs.",
  "games.teenpatti.rules.rules.4.h": "Pack",
  "games.teenpatti.rules.rules.5.body": "Only when two players are left. It costs your current bet. A seen player can’t ask a blind player for a show. Both hands are shown; on equal hands the player who asked loses.",
  "games.teenpatti.rules.rules.5.h": "Show",
  "games.teenpatti.rules.rules.6.body": "A seen player may pay a seen bet and ask the previous player still in (who must also be seen) to compare privately. They can accept — the lower hand packs, and on equal hands the asker packs — or deny, and play moves on.",
  "games.teenpatti.rules.rules.6.h": "Side show",
  "games.teenpatti.rules.rules.7.body": "When the pot reaches the limit (50 × boot by default), every hand still in is shown and the best takes the pot. Exact ties split.",
  "games.teenpatti.rules.rules.7.h": "Pot limit",
  "games.teenpatti.rules.rules.8.body": "Trail (three of a kind) > Pure sequence (straight flush) > Sequence > Colour (flush) > Pair > High card. A-K-Q is the top sequence, A-2-3 the second, then K-Q-J down to 4-3-2. No wrap-around (K-A-2). Suits never rank.",
  "games.teenpatti.rules.rules.8.h": "Hand ranks",
  "games.teenpatti.rules.rules.9.body": "Muflis: the lowest hand wins (the ranking is reversed). AK47: every Ace, King, 4 and 7 is wild. Joker: a card is cut each hand and its rank is wild. A wild card becomes whatever makes your best hand.",
  "games.teenpatti.rules.rules.9.h": "Variants",
