  "games.tiptap.faq.1.a": "The tiles slide back and no move is used — a swap only counts if it lines up 3 or more.",
  "games.tiptap.faq.1.q": "What happens if a swap makes no match?",
  "games.tiptap.faq.2.a": "Match 4 in a row for a Line, an L or T shape for a Bomb, and 5 in a row for a Prism.",
  "games.tiptap.faq.2.q": "How do I make a special tile?",
  "games.tiptap.faq.3.a": "The board reshuffles for free and tells you so.",
  "games.tiptap.faq.3.q": "What if there are no moves left?",
  "games.tiptap.faq.4.a": "Finish the goals for one star; leftover moves become bonus points, and beating the score marks earns two or three stars.",
  "games.tiptap.faq.4.q": "How do I get three stars?",
  "games.tiptap.faq.5.a": "Only your first try counts; replays are practice.",
  "games.tiptap.faq.5.q": "Does replaying the Daily count?",
  "games.tiptap.faq.6.a": "Swapping two specials fires a combo — for example Bomb + Bomb clears a 5×5 square and Prism + Prism clears the whole board.",
  "games.tiptap.faq.6.q": "What do two specials do together?",
