  "games.tiptap.replay_level_n_levels": "Replay level {{N_LEVELS}}",
  "games.tiptap.rules.glance.1": "Swap two neighbours to line up 3 or more of a colour",
  "games.tiptap.rules.glance.2": "Finish the level’s goals before your moves (or time) run out",
  "games.tiptap.rules.glance.3": "Bigger matches make specials",
  "games.tiptap.rules.rules.1.body": "Swap two touching tiles. The swap only counts if it makes a line of 3 or more; otherwise the tiles slide back and no move is used.",
  "games.tiptap.rules.rules.1.h": "Moves",
  "games.tiptap.rules.rules.2.body": "Match 4 in a row for a Line (clears its row or column, in the direction of the match). Match an L or T shape for a Bomb (clears a 3×3 square). Match 5 in a row for a Prism (clears every tile of one colour).",
  "games.tiptap.rules.rules.2.h": "Specials",
  "games.tiptap.rules.rules.3.body": "Swap two specials together: Line + Line clears a row and a column · Line + Bomb clears three rows and three columns · Bomb + Bomb clears a 5×5 square · Prism + Line or Bomb turns every tile of that colour into that special and fires them · Prism + Prism clears the whole board · Prism + a plain tile clears that colour.",
  "games.tiptap.rules.rules.3.h": "Combos",
  "games.tiptap.rules.rules.4.body": "After a clear, tiles fall and new ones drop in from the top. New lines clear automatically and score more with each step of the chain.",
  "games.tiptap.rules.rules.4.h": "Cascades",
  "games.tiptap.rules.rules.5.body": "Levels ask for a score, a number of tiles of one colour, clearing jelly tiles, breaking chains (chained tiles can’t move until a match next to or through them breaks the chain) or bringing fruit down to the bottom row. Some levels have a clock instead of a move limit.",
  "games.tiptap.rules.rules.5.h": "Goals",
  "games.tiptap.rules.rules.6.body": "Finish the goals for one star. Moves left over turn into bonus points; beat the level’s score marks for two or three stars.",
  "games.tiptap.rules.rules.6.h": "Stars",
  "games.tiptap.rules.rules.7.body": "If no swap can make a line, the board reshuffles for free and tells you so.",
  "games.tiptap.rules.rules.7.h": "No moves left",
  "games.tiptap.rules.rules.8.body": "One board a day, the same for everyone, 20 moves, highest score wins. Your first try counts; replay it as practice as often as you like.",
  "games.tiptap.rules.rules.8.h": "Daily",
  "games.tiptap.rules.ruleset.name": "{{@tiptap}} match-3",
  "games.tiptap.rules.ruleset.source": "Our own match-3 puzzle rules",
  "games.tiptap.rules.variant.mode.label": "Mode",
  "games.tiptap.score_fmt": "Score {{fmt}}",
