  "games.ttt.rules.glance.3": "Ultimate: nine small boards — win three in a row of them",
  "games.ttt.rules.rules.1.body": "Players alternate X and O on a 3×3 grid. Three in a row across, down or diagonally wins; a full board with no line is a draw. First move alternates each game.",
  "games.ttt.rules.rules.1.h": "Classic",
  "games.ttt.rules.rules.2.body": "Nine small boards make one big board. The square you play in sends your opponent to the matching small board. Win a small board with three in a row; win the game with three small boards in a row. If you are sent to a finished board, play anywhere. A drawn small board counts for nobody.",
  "games.ttt.rules.rules.2.h": "Ultimate",
  "games.ttt.rules.rules.3.body": "Classic: Easy, Medium (sometimes blunders) and Unbeatable — the Unbeatable bot always draws or wins. Ultimate: Easy, Normal and Hard.",
  "games.ttt.rules.rules.3.h": "Bots",
  "games.ttt.rules.rules.4.body": "Live 1v1 with a friend is unrated. Optional virtual-chip stake: the winner takes the other stake, a draw returns both. Leaving or timing out three times forfeits.",
