  "games.ttt.tip.ttt_alt": "First move alternates each game, so practise playing second too.",
  "games.ttt.tip.ttt_block": "Always check whether your opponent can win next move before making your own plan.",
  "games.ttt.tip.ttt_bot": "Try the Unbeatable bot — if you can draw it every time, you’ve got Classic solved.",
  "games.ttt.tip.ttt_centre": "If your opponent takes a corner, take the centre.",
  "games.ttt.tip.ttt_corner": "Corners are part of more lines than edges — a corner is a strong opening.",
  "games.ttt.tip.ttt_draw": "A draw — against good play that’s the fair result. Take a corner first and look for a move that makes two threats at once.",
  "games.ttt.tip.ttt_finished": "In Ultimate, a board sent to that’s already finished lets you play anywhere — a big advantage.",
  "games.ttt.tip.ttt_fork": "A fork — two lines that both need one more mark — wins because only one can be blocked.",
  "games.ttt.tip.ttt_loss": "Watch for a double threat: if your opponent can make two lines at once, block one move earlier.",
  "games.ttt.tip.ttt_ultimate": "In Ultimate, think about where your move sends your opponent — avoid sending them to a board they can win.",
