  "games.uno.round_round": "Round {{round}}",
  "games.uno.round_round_label": "Round {{round}} · {{label}}",
  "games.uno.rules": "How to play",
  "games.uno.rules.glance.1": "Match the top card by colour, number or symbol",
  "games.uno.rules.glance.2": "Skip, Reverse, Draw Two and Wilds change the game",
  "games.uno.rules.glance.3": "Empty your hand first — shout \"{{@ohno}}\" at one card",
  "games.uno.rules.rules.1.body": "108 cards: four colours of 0–9 (one 0, two of 1–9), two Skip, Reverse and Draw Two per colour, plus 4 Wilds and 4 Wild Draw Fours. Deal 7 each; 2–10 players.",
  "games.uno.rules.rules.1.h": "Deck",
  "games.uno.rules.rules.10.body": "20 seconds per turn. Miss it and you auto-draw, then pass; after 3 misses — or if you leave — a labelled bot finishes your seat and you place last.",
  "games.uno.rules.rules.10.h": "Live",
  "games.uno.rules.rules.11.body": "Optional virtual-chip stake. Everyone antes; placement by match score. 2 players: winner takes both · 3: 70/30 · 4: 60/30/10 · 5+: 50/30/20. Bots never take chips.",
  "games.uno.rules.rules.11.h": "Payouts",
  "games.uno.rules.rules.2.body": "Play a card matching the colour, number or symbol, or a Wild. You may draw instead, even if you could play; a playable drawn card may be played right away, otherwise play passes.",
  "games.uno.rules.rules.2.h": "Your turn",
  "games.uno.rules.rules.3.body": "Wild Draw Four: reshuffle and flip again. Wild: the first player picks the colour. Draw Two: the first player draws 2 and is skipped. Reverse: play starts with the dealer, going the other way. Skip: the first player is skipped.",
  "games.uno.rules.rules.3.h": "Starting card",
  "games.uno.rules.rules.4.body": "Skip: next player misses a turn. Reverse: direction flips (with 2 players it acts as a Skip). Draw Two: next player draws 2 and is skipped. Wild: pick the colour.",
  "games.uno.rules.rules.4.h": "Action cards",
  "games.uno.rules.rules.5.body": "Only legal when you hold no card of the current colour. The next player may challenge: if you bluffed you draw 4; if you were honest they draw 6. The challenger privately sees your hand. Unchallenged: they draw 4 and are skipped.",
  "games.uno.rules.rules.5.h": "Wild Draw Four",
  "games.uno.rules.rules.6.body": "Tap \"{{@ohno}}\" as you play your second-to-last card. If someone taps \"Catch!\" before the next player starts their turn, you draw 2.",
  "games.uno.rules.rules.6.h": "{{@ohno}}",
  "games.uno.rules.rules.7.body": "When it runs out, the discards (except the top card) are reshuffled.",
  "games.uno.rules.rules.7.h": "Draw pile",
  "games.uno.rules.rules.8.body": "The first to empty their hand scores the cards left in everyone else’s: numbers at face value, Skip / Reverse / Draw Two 20, Wilds 50. Play a single round, or to 250 or 500.",
  "games.uno.rules.rules.8.h": "Scoring",
  "games.uno.rules.rules.9.body": "Optional, locked when the game starts and shown in the lobby: Stacking (with a mix option), Jump-In, 7-0, Draw until playable, Force play, No bluffing, Quick round (5 cards).",
  "games.uno.rules.rules.9.h": "House rules",
